package com.maurodelcore.expensetracker.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import lombok.Data;

/**
 * JPA entity representing a single expense record, owned by one {@link AppUser}.
 * {@code @Data} generates getters, setters, {@code equals}/{@code hashCode}, and {@code toString}.
 */
@Entity
@Data
public class Expense {

    /**
     * Primary key that uniquely identifies each expense, generated by the database.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Numeric code for the type of expense.
     */
    private int expenseType;

    /**
     * The date of the expense, stored as text.
     */
    private String date;

    /**
     * The amount of money spent.
     */
    private Double amount;

    /**
     * The category of the expense (for example "Food").
     */
    private String category;

    /**
     * The account the expense was paid from.
     */
    private String account;

    /**
     * An optional free-text note about the expense.
     */
    private String note;

    /**
     * The user who owns this expense. Each expense belongs to a single user and is
     * loaded from the database only when this field is accessed (lazy fetching).
     * The {@code user_id} column joins to the users table. Excluded from the JSON output.
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    @JsonIgnore
    private AppUser user;
}